head.b:skin:
/* Theme Name: KNOW-AI - Premium Universal Engine
Author: AI Collaborator
Year: 2026
*/
body {
  background-color: #020617;
  color: #f1f5f9;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: #0b1329; }
::-webkit-scrollbar-thumb { background: #1e293b; border-radius: 10px; }

/* Hard Reset & Kill Switch untuk Elemen Bawaan Blogger */
.abc-container, #abc, .section, .widget, #navbar, .Header, .Blog { 
  display: none !important; 
  visibility: hidden !important; 
  height: 0 !important; 
  width: 0 !important; 
  opacity: 0 !important; 
  overflow: hidden !important;
}

body.script:
    //

    let isDataLocked = false;
    let isParamsLocked = false;

    // DEFINISI URL DEFAULT UTAMA (IAHPC MANUAL OF PALLIATIVE CARE 3E)
    const DEFAULT_URL = "https://iahpc.org/uploads/2013/9/The%20IAHPC%20Manual%20of%20Palliative%20Care%203e.pdf";

    // DEFINISI KELAS WARNA GELAP METALIK UNTUK RESET KONSISTENSI VISUAL
    const DARK_METAL_CLASS = 'w-full py-2.5 bg-gradient-to-r from-slate-900 via-slate-800 to-zinc-900 hover:from-slate-800 hover:to-zinc-800 text-slate-200 border border-slate-700/50 font-bold text-xs uppercase tracking-wider rounded-xl shadow-md transition-all cursor-pointer';
    const DARK_METAL_CLASS_PARAMS = 'w-full py-2 bg-gradient-to-r from-slate-900 via-slate-800 to-zinc-900 hover:from-slate-800 hover:to-zinc-800 text-slate-200 border border-slate-700/50 font-bold text-[11px] uppercase tracking-wider rounded-xl shadow-md transition-all cursor-pointer';

    function resolveTargetParameters() {
        const manualTitle = document.getElementById('sourceTitleInput').value.trim();
        const manualUrl = document.getElementById('customUrlInput').value.trim();
        return { 
            title: manualTitle || "General Clinical Guidelines (Palliative Engine)", 
            url: manualUrl || DEFAULT_URL 
        };
    }

    function generateStrictContextDirective(target) {
        return `[STRICT CONTEXT BINDING & NARRATIVE LENGTH PROTOCOL]:
- Topik / Kasus Spesifik yang diekstrak: "${target.title}".
- Sumber Utama / URL Makro: <${target.url}>.
- ATURAN VALIDASI KONTEKS: Jika URL memuat data yang sangat luas, fokuskan analisis dan ekstraksi HANYA pada sub-topik "${target.title}". Jangan lakukan generalisasi ke bab lain yang tidak relevan.
- ATURAN KUALITAS & PANJANG NASKAH: DILARANG memberikan jawaban yang terlalu pendek, seadanya, atau hanya ringkasan poin-poin singkat. Anda harus menyusun naskah narasi yang lengkap, matang, mengalir secara profesional, kaya penjelasan klinis, detail, dan mencakup seluruh aspek instruksi di bawah ini agar layak dan siap pakai sebagai dokumen rujukan medis profesional tanpa revision panjang.`;
    }

    function updateSystemIndicator(text, mode = 'normal') {
        const el = document.getElementById('systemStatus');
        el.innerText = `⚡ ${text.toUpperCase()}`;

        if(mode === 'success') el.className = "text-[10px] md:text-xs font-bold text-emerald-400 tracking-wider uppercase animate-pulse";
        else if(mode === 'lock') el.className = "text-[10px] md:text-xs font-bold text-cyan-400 tracking-wider uppercase";
        else el.className = "text-[10px] md:text-xs font-semibold text-slate-500 tracking-wider uppercase";

        setTimeout(() => {
            let statusText = "🚀 UNIVERSAL PIPELINE CONFIGURATION READY";
            let statusClass = "text-[10px] md:text-xs font-semibold text-slate-500 tracking-wider uppercase";

            if (isDataLocked && isParamsLocked) {
                statusText = "🔒 MAXIMUM SECURE MODE: ALL ARCHITECTURES LOCKED";
                statusClass = "text-[10px] md:text-xs font-bold text-emerald-500 tracking-wider uppercase";
            } else if (isDataLocked) {
                statusText = "⚡ LITERATUR DATA STRUCTURE LOCKED";
                statusClass = "text-[10px] md:text-xs font-bold text-cyan-500 tracking-wider uppercase";
            } else if (isParamsLocked) {
                statusText = "⚙️ CLINICAL PARAMETERS ARCHITECTURE LOCKED";
                statusClass = "text-[10px] md:text-xs font-bold text-amber-500 tracking-wider uppercase";
            }

            el.innerText = statusText;
            el.className = statusClass;
        }, 2000);
    }

    // SUNTIKAN 3: TOAST FLASH FEEDBACK LUXURY UX ON CLICK BUTTONS
    function animateButtonLabel(id, parentButtonId) {
        const el = document.getElementById(id);
        const parentBtn = document.getElementById(parentButtonId);
        const oldText = el.innerText;

        el.innerText = "COPIED! ✓";
        if(parentBtn && parentButtonId.startsWith('btnGen')) {
            parentBtn.classList.add('bg-slate-800', 'border-emerald-500/80');
        }

        setTimeout(() => { 
            el.innerText = oldText; 
            if(parentBtn && parentButtonId.startsWith('btnGen')) {
                parentBtn.classList.remove('bg-slate-800', 'border-emerald-500/80');
            }
        }, 1200);
    }

    function safeCopy(text, callback) {
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(text).then(() => { if(callback) callback(); });
        } else {
            const ta = document.createElement("textarea"); ta.value = text;
            ta.style.position = "fixed"; ta.style.opacity = "0"; document.body.appendChild(ta);
            ta.focus(); ta.select(); document.execCommand('copy');
            document.body.removeChild(ta); if(callback) callback();
        }
    }

    // NATIVE CLIPBOARD PASTE INTERACTION ENGINE
    document.getElementById('btnPasteUrl').onclick = function() {
        if (navigator.clipboard && navigator.clipboard.readText) {
            navigator.clipboard.readText()
            .then(text => {
                document.getElementById('customUrlInput').value = text;
                updateSystemIndicator("URL Berhasil Ditempel!", "success");
            })
            .catch(err => {
                alert("Gagal membaca clipboard otomatis. Izinkan akses clipboard di browser Anda.");
            });
        } else {
            alert("Fitur auto-paste membutuhkan jaringan https aman (Secure Context).");
        }
    };

    // INTERACTIVE LOCK ENGINE: MODUL LITERATUR
    document.getElementById('btnLockData').onclick = function() {
        const lockBtn = document.getElementById('btnLockData');
        const pasteBtn = document.getElementById('btnPasteUrl');
        const tInput = document.getElementById('sourceTitleInput');
        const uInput = document.getElementById('customUrlInput');

        if(!isDataLocked) {
            isDataLocked = true;
            tInput.disabled = uInput.disabled = pasteBtn.disabled = true;
            if(uInput.value.trim() === "") {
                uInput.value = DEFAULT_URL;
            }
            lockBtn.innerText = "🔓 BUKA EDIT MODUL LITERATUR";
            lockBtn.className = 'w-full py-2.5 bg-slate-800 text-cyan-400 border border-slate-700 font-bold text-xs uppercase tracking-wider rounded-xl transition-all cursor-pointer text-center';
            updateSystemIndicator("Data Literatur Terkunci!", 'lock');
        } else {
            isDataLocked = false;
            tInput.disabled = uInput.disabled = pasteBtn.disabled = false;
            if(uInput.value === DEFAULT_URL) {
                uInput.value = "";
            }
            lockBtn.innerText = "🔒 KUNCI DATA LITERATUR MEDIS";
            lockBtn.className = DARK_METAL_CLASS;
            updateSystemIndicator("Modul Literatur Aktif", 'normal');
        }
    };

    // INTERACTIVE LOCK ENGINE: MODUL PARAMETER
    document.getElementById('btnLockParams').onclick = function() {
        const lockBtn = document.getElementById('btnLockParams');
        const sScale = document.getElementById('clinicalScale');
        const cContext = document.getElementById('culturalContext');
        const nNotes = document.getElementById('customNotes');

        if(!isParamsLocked) {
            isParamsLocked = true;
            sScale.disabled = cContext.disabled = nNotes.disabled = true;
            lockBtn.innerText = "🔓 BUKA EDIT PARAMETER LOKALISASI";
            lockBtn.className = 'w-full py-2 bg-slate-800 text-amber-400 border border-slate-700 font-bold text-[11px] uppercase tracking-wider rounded-xl transition-all cursor-pointer text-center';
            updateSystemIndicator("Parameter Klinis Terkunci!", 'lock');
        } else {
            isParamsLocked = false;
            sScale.disabled = cContext.disabled = nNotes.disabled = false;
            lockBtn.innerText = "🔒 KUNCI PARAMETER LOKALISASI";
            lockBtn.className = DARK_METAL_CLASS_PARAMS;
            updateSystemIndicator("Modul Parameter Aktif", 'normal');
        }
    };

    // FASE 1: CLINICAL SUMMARY
    document.getElementById('btnGen1').onclick = function() {
        const target = resolveTargetParameters();
        const strictRules = generateStrictContextDirective(target);
        const scale = document.getElementById('clinicalScale').value;
        const context = document.getElementById('culturalContext').value;
        const notes = document.getElementById('customNotes').value;

        const prompt = `Act as an Expert Palliative Care Clinician. 
${strictRules}

Task: Susun sebuah narasi ekstensif mengenai ekstraksi definisi dasar, intervensi akut, dan sinkronisasi menyeluruh pada skala evaluasi "${scale}" dengan target audiens/konteks: "${context}". Elaborasi narasi secara detail, jelas, berbobot, dan tidak terburu-buru dalam mengambil kesimpulan.
${notes ? `[CATATAN INJEKSI KHUSUS]: ${notes}` : ""}
Language: Formal Medical Indonesian. End with: "--- CLINICAL SUMMARY COMPLETE ---"`;

        safeCopy(prompt, () => { updateSystemIndicator("Fase 1 Copied!", 'success'); animateButtonLabel('lblGen1', 'btnGen1'); });
    };

    // FASE 2: DIFFERENTIAL DIAGNOSIS
    document.getElementById('btnGen2').onclick = function() {
        const target = resolveTargetParameters();
        const strictRules = generateStrictContextDirective(target);
        const prompt = `Act as a Senior Clinical Pharmacologist and Palliative Diagnostic Expert.
${strictRules}

Based on the target segment [${target.title}], generate a comprehensive and deeply analytical narrative text containing:
1. Differential Diagnostics & Co-morbidity Layering yang dijabarkan secara rinci dan teoretis berdasar kasus terkait.
2. High-Alert Drug Interactions atau profil keamanan obat dalam fase paliatif (bahas mekanisme interaksi secara deskriptif dan panjang).
3. Explicit Red Flags (Tanda kegawatdaruratan klinis nyata yang memerlukan eksalasi instan ke IGD rumah sakit terdekat).
Tuliskan dalam bentuk naskah rujukan medis yang tebal dan berbobot.
Language: Authoritative Medical Indonesian. End with: "--- DIAGNOSTIC & PHARMACOLOGICAL SAFETY COMPLETED ---"`;

        safeCopy(prompt, () => { updateSystemIndicator("Fase 2 Copied!", 'success'); animateButtonLabel('lblGen2', 'btnGen2'); });
    };

    // FASE 3: BIO-PSYCHO-SOCIAL-SPIRITUAL
    document.getElementById('btnGen3').onclick = function() {
        const target = resolveTargetParameters();
        const strictRules = generateStrictContextDirective(target);
        const context = document.getElementById('culturalContext').value;
        const prompt = `Act as a Medical Anthropologist and Palliative Care Social Worker.
${strictRules}

Based exclusively on the isolated subtopic [${target.title}], compile a full-length, deeply moving, and clinically structured Bio-Psycho-Social-Spiritual Care Plan narrative optimized for: "${context}".
Jabarkan secara panjang dan deskriptif mengenai manajemen 'Total Pain' (Nyeri Total) yang menyangkut dinamika psikologis keluarga, tabu budaya lokal yang harus dihindari, serta panduan naratif untuk dukungan duka cita (grief support) spiritual.
Language: Highly empathetic, elegant Indonesian. End with: "--- HOLISTIC TOTAL PAIN MAP COMPLETED ---"`;

        safeCopy(prompt, () => { updateSystemIndicator("Fase 3 Copied!", 'success'); animateButtonLabel('lblGen3', 'btnGen3'); });
    };

    // FASE 4: INFOGRAPHIC COMPREHENSIVE BLUEPRINT
    document.getElementById('btnGen4').onclick = function() {
        const target = resolveTargetParameters();
        const strictRules = generateStrictContextDirective(target);
        const context = document.getElementById('culturalContext').value;
        const prompt = `Act as an Elite Medical Copywriter. 
${strictRules}

Transform the substance of [${target.title}] into a highly structured, elaborate Infographic Blueprint for visual designers. Naskah blueprint ini harus panjang dan siap cetak/desain, bukan ringkasan kasar.
Sediakan: Komponen Headline Lokal, Rekomendasi Palet Warna Psikologis, dan breakdown 4 Bagian utama Konten di mana tiap bagian memuat Petunjuk Visual (Visual Instructions) yang detil serta Naskah Pendek Penyuluhan (Indonesian Copywriting) yang naratif, persuasif, dan menyentuh.
Tone: tailored specifically for "${context}". End with: "--- INFOGRAPHIC SCRIPT BLUEPRINT GENERATED ---"`;

        safeCopy(prompt, () => { updateSystemIndicator("Fase 4 Copied!", 'success'); animateButtonLabel('lblGen4', 'btnGen4'); });
    };

    // FASE 5: INTERDISCIPLINARY SCRIPT
    document.getElementById('btnGen5').onclick = function() {
        const target = resolveTargetParameters();
        const strictRules = generateStrictContextDirective(target);
        const prompt = `Act as a Palliative Care Liaison Officer. 
${strictRules}

Develop an extensive Interdisciplinary Communication Script focusing on the clinical management of [${target.title}]. 
Buatlah naskah dialog serah terima (handover) yang panjang, komplet, dan realistis menggunakan format SBAR secara utuh untuk 3 skenario: Naskah Dokter ke Perawat, Naskah Tim Medis ke Keluarga/Caregiver utama, dan Naskah Komunikasi Relawan Lapangan. Jangan gunakan ringkasan poin, tuliskan percakapan/skrip lengkapnya.
Language: Clear, actionable Indonesian. End with: "--- INTERDISCIPLINARY COMMUNICATION HANDOVER COMPLETED ---"`;

        safeCopy(prompt, () => { updateSystemIndicator("Fase 5 Copied!", 'success'); animateButtonLabel('lblGen5', 'btnGen5'); });
    };

    // FASE 6: AI INTERACTIVE PATIENT SIMULATOR
    document.getElementById('btnGen6').onclick = function() {
        const target = resolveTargetParameters();
        const strictRules = generateStrictContextDirective(target);
        const prompt = `Act as a specialized AI Clinical Simulation Actor roleplaying as an anxious primary caregiver of a terminal patient affected specifically by [${target.title}].
${strictRules}

Rules: Never break character, no meta-commentary, start from deep denial/anxiety concerning this exact sub-topic condition. Tuliskan tanggapan awal yang sarat emosi, ketakutan, atau keberatan adat/spiritual (panjang 2-3 kalimat yang berbobot secara psikologis) untuk memicu dan memaksa user berlatih komunikasi terapeutik empati secara mendalam dalam Bahasa Indonesia. Begin simulation now.`;

        safeCopy(prompt, () => { updateSystemIndicator("Fase 6 Copied!", 'success'); animateButtonLabel('lblGen6', 'btnGen6'); });
    };

    // GLOBAL MASTER PROMPT SUMMARY
    document.getElementById('btnGlobalSummary').onclick = function() {
        const target = resolveTargetParameters();
        const strictRules = generateStrictContextDirective(target);
        const scale = document.getElementById('clinicalScale').value;
        const context = document.getElementById('culturalContext').value;
        const notes = document.getElementById('customNotes').value;

        const globalPrompt = `[MASTER 6-LAYER CLINICAL INTELLIGENCE PROMPT SUMMARY]
======================================================
${strictRules}
======================================================
DEPLOYMENT ARCHITECTURE PARAMETERS:
- Evaluation Framework Scale: ${scale}
- Socio-Cultural Localization: ${context}
- Special Injection Notes: ${notes || "None"}
======================================================
MANDATE TASK: Lakukan pemrosesan sumber di atas dengan restriksi mikro-konteks yang ketat serta protokol kepanjangan naskah narasi yang utuh. Hasilkan output komprehensif dalam bentuk 6 Bagian Utama (Tulis naskah penuh untuk tiap bagian, dilarang memotong isi atau membuat rangkuman pendek):
1. Clinical Summary (Cornerstone focused on Sub-topic)
2. Differential Diagnosis & Safety Layering (Analytical and deep)
3. Holistic Bio-Psycho-Social-Spiritual Plan (Long care plan text)
4. Infographic Ready Script & Micro-copy (Complete visual copy blueprint)
5. Interdisciplinary SBAR Handover Script (Full conversational script)
6. Initiate preparation for Interactive Caregiver Simulation (Emotional prompt starter).
Language Target: Expert & Empathetic Indonesian. All answers must be extensive and highly professional.`;

        safeCopy(globalPrompt, () => { updateSystemIndicator("Master Summary Copied!", 'success'); animateButtonLabel('btnGlobalSummary', 'btnGlobalSummary'); });
    };

    // RESET SYSTEM
    document.getElementById('btnResetPlatform').onclick = function() {
        isDataLocked = false;
        isParamsLocked = false;

        document.getElementById('sourceTitleInput').disabled = document.getElementById('customUrlInput').disabled = document.getElementById('btnPasteUrl').disabled = false;
        document.getElementById('clinicalScale').disabled = document.getElementById('culturalContext').disabled = document.getElementById('customNotes').disabled = false;

        document.getElementById('sourceTitleInput').value = document.getElementById('customUrlInput').value = document.getElementById('customNotes').value = "";
        document.getElementById('clinicalScale').selectedIndex = 0;
        document.getElementById('culturalContext').selectedIndex = 0;

        document.getElementById('btnLockData').innerText = "🔒 KUNCI DATA LITERATUR MEDIS";
        document.getElementById('btnLockData').className = DARK_METAL_CLASS;

        document.getElementById('btnLockParams').innerText = "🔒 KUNCI PARAMETER LOKALISASI";
        document.getElementById('btnLockParams').className = DARK_METAL_CLASS_PARAMS;

        updateSystemIndicator("System Cleared & Reset Success");
    };

    //
